create table sales_plans (id uuid primary key default gen_random_uuid(),target_month date not null check(target_month=date_trunc('month',target_month)),po_no text not null unique,service_po_no text,po_date date not null,shipper_id uuid not null references shippers(shipper_id),unit_rate_usd numeric(16,4) not null check(unit_rate_usd>=0),created_at timestamptz not null default now());
create table sales_plan_lines (id uuid primary key default gen_random_uuid(),sales_plan_id uuid not null references sales_plans(id) on delete cascade,product_name text not null references products(product_name),target_containers numeric(14,3) not null check(target_containers>=0),per_container_amount numeric(16,4) not null check(per_container_amount>=0),unique(sales_plan_id,product_name));
create table sales_updates (id uuid primary key default gen_random_uuid(),sales_date date not null,po_no text not null references sales_plans(po_no),shipper_id uuid not null references shippers(shipper_id),service_po_no text,product_name text not null references products(product_name),billed_containers numeric(14,3) not null check(billed_containers>=0),shipper_inv_no text not null unique,invoice_amount_inr numeric(16,2) not null check(invoice_amount_inr>=0),shipper_service_inv_no text,service_invoice_amount_inr numeric(16,2) not null default 0 check(service_invoice_amount_inr>=0));
create index sales_updates_invoice_date_idx on sales_updates(sales_date,shipper_inv_no); create index sales_updates_product_idx on sales_updates(product_name);

